<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const projectViewStates = new Map();
    let projectListState = { filter: 'Active', query: '', appliedQuery: '' };
    const foldAscii = (value) => value.replace(/[A-Z]/g, (letter) => letter.toLowerCase());
    const normalizeSearchText = (value) => foldAscii(value.replace(/[ \t]+/g, ' '));
    const requestProjects = async (options) => {
      const response = await fetch('/api/projects', options);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestTasks = async (projectId, options) => {
