      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        try {
          await requestProjects({ method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: input.value }) });
          renderList(await requestProjects());
        } catch (error) {
          alert.textContent = error.message;
          alert.hidden = false;
        }
      });
      app.append(form, alert);
      const filterField = document.createElement('div');
      filterField.className = 'filter';
      const filterLabel = document.createElement('label');
      filterLabel.htmlFor = 'project-filter';
      filterLabel.textContent = 'Project filter';
      const filter = document.createElement('select');
      filter.id = 'project-filter';
      for (const value of ['Active', 'Archived']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        option.selected = value === selectedFilter;
        filter.append(option);
      }
      filterField.append(filterLabel, filter);
      app.append(filterField);
      const searchForm = document.createElement('form');
      const searchField = document.createElement('div');
      const searchLabel = document.createElement('label');
      searchLabel.htmlFor = 'project-search';
      searchLabel.textContent = 'Project search';
      const searchInput = document.createElement('input');
      searchInput.id = 'project-search';
      searchInput.type = 'text';
      searchInput.value = projectListState.query;
      searchField.append(searchLabel, searchInput);
      const searchButton = document.createElement('button');
      searchButton.type = 'submit';
      searchButton.textContent = 'Search projects';
      searchForm.append(searchField, searchButton);
      const renderProjects = () => {
        for (const row of app.querySelectorAll('[data-testid="project-row"]')) row.remove();
        const query = normalizeSearchText(projectListState.appliedQuery);
        for (const project of projects.filter((item) => item.archived === (filter.value === 'Archived')
